    # Vertical marker columns are indicated by isolated colored cells near
    # the bottom. Extend each through the grid, with each horizontal gap
    # setting the color of the section above it.
    marker_cols = set()
    for r in range(h - 2, h):
        for c in range(w):
            if grid[r][c] != 0:
                marker_cols.add(c)

    for c in marker_cols:
        markers = [(r, grid[r][c]) for r in range(h - 2, h) if grid[r][c] != 0]
        marker_color = markers[-1][1]
        levels = sorted(gap_colors.get(c, []))
        if not levels:
            continue
        for r in range(h):
            below = [(rr, color) for rr, color in levels if rr >= r]
            g[r][c] = below[0][1] if below else marker_color

    return g
